/* ===== 1. 隐藏头像且不占位（官方支持，心声仍可点击） ===== */
.msg-avatar-me-container { 
  display: none !important; 
}

/* ===== 2. 气泡整体等比例缩小与颜色设定 ===== */
:root {
  /* --- 气泡等比缩小（字号与内边距） --- */
  --bubble-me-font-size: 13px;       /* 默认通常为 15px，缩小到 13px */
  --bubble-them-font-size: 13px;
  --bubble-me-padding: 8px 12px;     /* 缩小内边距，让气泡看起来更紧凑 */
  --bubble-them-padding: 8px 12px;

  /* --- 我方气泡 (颜色与缩小后的圆角) --- */
  --bubble-me-bg: #F2F3F7;
  --bubble-me-color: #262626; 
  /* 配合缩小的气泡，把原本 20px 的圆角按比例缩到 16px，右下角保持 0px */
  --bubble-me-radius: 16px 16px 0px 16px;
  --bubble-me-radius-first: 16px 16px 0px 16px;
  --bubble-me-radius-mid: 16px 16px 0px 16px;
  --bubble-me-radius-last: 16px 16px 0px 16px;

  /* --- 对方气泡 (颜色与缩小后的圆角) --- */
  --bubble-them-bg: #BCF3F6;
  --bubble-them-color: #262626;
  /* 配合缩小的气泡，把原本 20px 的圆角按比例缩到 16px，左上角保持 0px */
  --bubble-them-radius: 0px 16px 16px 16px;
  --bubble-them-radius-first: 0px 16px 16px 16px;
  --bubble-them-radius-mid: 0px 16px 16px 16px;
  --bubble-them-radius-last: 0px 16px 16px 16px;
}
:root {
  /* ===== 1. 永远直接显示翻译，不需要点击 ===== */
  --translation-always-show: 1;

  /* ===== 2. 翻译区块去方块化，改为虚线分割 ===== */
  --translation-bg: transparent;         /* 去除原本的方块背景色 */
  --translation-radius: 0px;             /* 去除圆角 */
  --translation-shadow: none;            /* 去除阴影 */

  /* 上方加一条虚线（可以根据需要调整颜色和粗细） */
  --translation-separator: 1px dashed rgba(0, 0, 0, 0.25); 

  /* 调整间距：让左右和原文字对齐，上下留出呼吸感 */
  --translation-margin: 6px 0 0 0;       /* 虚线距离上方原文字的距离 */
  --translation-padding: 8px 0 0 0;      /* 翻译文字距离上方虚线的距离 */

  /* ===== 3. 翻译文字的美化（可选） ===== */
  --translation-text-color: inherit;     /* 翻译颜色默认跟随原文字 */
  --translation-opacity: 0.7;            /* 稍微降低翻译文字的透明度，用来区分原文和译文 */
  --translation-size: 12px;              /* 翻译字号（比气泡字号13px再小一点点） */
}
/* 如果翻译内容完全为空，则彻底隐藏该区块和虚线 */
.msg-translation-content:empty {
  display: none !important;
}
.msg-translation-wrapper:has(.msg-translation-content:empty) {
  display: none !important;
}
/* 1. 让包裹“气泡+状态”的容器成为定位基准，并允许内容溢出 */
.msg-me .msg-content-stack {
  position: relative !important;
  overflow: visible !important; 
}

/* 2. 将原本在下方的状态文字绝对定位到左侧外面 */
.msg-me .msg-status-custom {
  position: absolute !important;
  right: 100% !important;         /* 把文字挤到气泡容器的最左侧外 */
  bottom: 0px !important;         /* 垂直方向与气泡的底部对齐 */
  margin-right: 8px !important;   /* 文字与气泡之间的距离，可自行改大小 */
  margin-top: 0px !important;     /* 清除原本默认的上方间距 */
  margin-bottom: 2px !important;  /* 微调对齐高度，让它看着更居中或平齐 */
  white-space: nowrap !important; /* 强制时间和已读文字保持在同一行，不换行 */
  text-align: right !important;   /* 文字靠右贴紧气泡 */
}
/* ================================================= */
